/**
 * Extracts `@handle` mentions from comment bodies and resolves them to member
 * ids.
 *
 * A handle is the local part of a member's email address, lowercased — that
 * is what the comment composer autocompletes and what `CommentService` feeds
 * to the notification fan-out, so extraction and resolution must agree
 * exactly. Mentions inside code spans and fenced blocks are ignored.
 */
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";

/** `@` must start the line or follow whitespace/punctuation, never an email. */
const MENTION_PATTERN = /(^|[\s(<[])@([a-z0-9][a-z0-9._-]{0,38}[a-z0-9])/gi;

function withoutCode(body: string): string {
  return body.replace(/```[\s\S]*?```/g, " ").replace(/`[^`]*`/g, " ");
}

/** The handle Taskflow addresses a member by, derived from their email. */
export function handleOf(member: MemberWithUser): string {
  return (member.user.email.split("@")[0] ?? "").toLowerCase();
}

/** Every distinct handle mentioned, in first-appearance order. */
export function extractMentions(body: string): readonly string[] {
  const seen = new Set<string>();
  const handles: string[] = [];

  for (const match of withoutCode(body).matchAll(MENTION_PATTERN)) {
    const handle = (match[2] ?? "").toLowerCase();
    if (handle === "" || seen.has(handle)) continue;
    seen.add(handle);
    handles.push(handle);
  }

  return handles;
}

/**
 * Maps the mentions in `body` onto the ids of members who actually exist in
 * the organization. Unknown handles are silently dropped — a typo must never
 * fail the comment write.
 */
export function resolveMentions(
  body: string,
  members: readonly MemberWithUser[],
): readonly UserId[] {
  const byHandle = new Map<string, UserId>();
  for (const member of members) {
    // Read-only members cannot take part in a discussion, so pinging them
    // only produces an alert they can do nothing about.
    if (member.role === "viewer") continue;
    byHandle.set(handleOf(member), member.userId);
  }

  const resolved: UserId[] = [];
  const seen = new Set<UserId>();
  for (const handle of extractMentions(body)) {
    const userId = byHandle.get(handle);
    if (userId === undefined || seen.has(userId)) continue;
    seen.add(userId);
    resolved.push(userId);
  }

  return resolved;
}

/** Wraps every mention in a span so the comment renderer can style it. */
export function highlightMentions(body: string): string {
  return body.replace(
    MENTION_PATTERN,
    (_match, prefix: string, handle: string) =>
      `${prefix}<span class="mention">@${handle}</span>`,
  );
}
/**
 * Token-bucket limiter applied to invites, comments, search and password
 * resets.
 *
 * Buckets are keyed by `(orgId, bucketKey)` and held in process — Taskflow
 * runs single-writer, and the corpus has no external cache. Capacity scales
 * with the org's plan through `getPlanLimits()`, so a growth org is not held
 * to a free org's ceiling; the per-bucket shape below is the base rate.
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { PlanId } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

export type RateLimitVerdict = {
  allowed: boolean;
  remaining: number;
  resetAt: IsoTimestamp;
};

export type RateLimitConfig = { capacity: number; refillPerMinute: number };

export const RATE_LIMIT_BUCKETS: Readonly<Record<string, RateLimitConfig>> = {
  "member:invite": { capacity: 20, refillPerMinute: 2 },
  "comment:create": { capacity: 60, refillPerMinute: 20 },
  "issue:create": { capacity: 60, refillPerMinute: 20 },
  "search:query": { capacity: 120, refillPerMinute: 60 },
  "auth:password-reset": { capacity: 5, refillPerMinute: 1 },
  "webhook:deliver": { capacity: 100, refillPerMinute: 50 },
};

/** Applied to any key not in the table above. */
const DEFAULT_BUCKET: RateLimitConfig = { capacity: 30, refillPerMinute: 10 };

type BucketState = { tokens: number; updatedAt: number };

const buckets = new Map<string, BucketState>();

/** Plan-aware org context; services set this when they know the org's plan. */
const planByOrg = new Map<OrgId, PlanId>();

/** Records an org's plan so subsequent bucket sizes scale with its quota. */
export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
  planByOrg.set(orgId, plan);
}

export function getBucketConfig(bucketKey: string): RateLimitConfig {
  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;
}

/**
 * Scales the base bucket by the org's hourly API allowance, so the limiter
 * and the plan catalogue can never drift apart: the plan is the source of
 * the ceiling, this table only sets the relative shape.
 */
function configFor(orgId: OrgId, bucketKey: string): RateLimitConfig {
  const base = getBucketConfig(bucketKey);
  const plan = planByOrg.get(orgId) ?? "free";
  const hourly = getPlanLimits(plan).apiRequestsPerHour;
  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;

  return {
    capacity: Math.min(base.capacity * factor, base.capacity * 100),
    refillPerMinute: Math.min(
      base.refillPerMinute * factor,
      base.refillPerMinute * 100,
    ),
  };
}

/**
 * Spends `cost` tokens from the bucket, refilling first for the elapsed time.
 * Async because the production limiter is expected to move behind a store —
 * every call site already awaits it.
 */
export async function consumeRateLimit(
  orgId: OrgId,
  bucketKey: string,
  cost = 1,
): Promise<RateLimitVerdict> {
  const config = configFor(orgId, bucketKey);
  const key = `${orgId}:${bucketKey}`;
  const nowMs = Date.now();

  const state = buckets.get(key) ?? { tokens: config.capacity, updatedAt: nowMs };
  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
  const tokens = Math.min(
    config.capacity,
    state.tokens + elapsedMinutes * config.refillPerMinute,
  );

  const allowed = tokens >= cost;
  const remaining = allowed ? tokens - cost : tokens;
  buckets.set(key, { tokens: remaining, updatedAt: nowMs });

  const deficit = allowed ? config.capacity - remaining : cost - remaining;
  const minutesToReset =
    config.refillPerMinute > 0 ? Math.max(0, deficit) / config.refillPerMinute : 0;

  return {
    allowed,
    remaining: Math.floor(remaining),
    resetAt: toIsoTimestamp(new Date(nowMs + minutesToReset * 60_000)),
  };
}

/** Test-only: drops every bucket and org plan association. */
export function resetRateLimits(): void {
  buckets.clear();
  planByOrg.clear();
}
import type {
  CommentId,
  IssueId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";
import type { User } from "./member";

export interface Comment extends Timestamps, TenantScoped, SoftDeletable {
  readonly id: CommentId;
  readonly issueId: IssueId;
  readonly authorId: UserId;
  readonly body: string;
  readonly parentId: CommentId | null;
  readonly editedAt: string | null;
  readonly mentionedUserIds: readonly UserId[];
}

export interface CommentWithAuthor extends Comment {
  readonly author: User;
}

/** A top-level comment plus its replies, as rendered by `CommentThread`. */
export interface CommentThreadNode {
  readonly comment: CommentWithAuthor;
  readonly replies: readonly CommentWithAuthor[];
}

export interface CommentDraft {
  readonly issueId: IssueId;
  readonly body: string;
  readonly parentId: CommentId | null;
}
import { z } from "zod";
import {
  commentIdSchema,
  issueIdSchema,
  orgIdSchema,
  pageRequestSchema,
  userIdSchema,
} from "./common";

export const createCommentSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  body: z.string().min(1, "write something").max(10_000),
  parentId: commentIdSchema.nullable().default(null),
  mentionedUserIds: z.array(userIdSchema).max(50).default([]),
});

export const updateCommentSchema = z.object({
  orgId: orgIdSchema,
  commentId: commentIdSchema,
  body: z.string().min(1).max(10_000),
});

export const deleteCommentSchema = z.object({
  orgId: orgIdSchema,
  commentId: commentIdSchema,
});

export const listCommentsSchema = z
  .object({
    orgId: orgIdSchema,
    issueId: issueIdSchema,
    includeArchived: z.boolean().default(false),
  })
  .extend(pageRequestSchema.shape);

export type CreateCommentInput = z.infer<typeof createCommentSchema>;
export type UpdateCommentInput = z.infer<typeof updateCommentSchema>;
export type DeleteCommentInput = z.infer<typeof deleteCommentSchema>;
export type ListCommentsInput = z.infer<typeof listCommentsSchema>;
/**
 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { toIsoTimestamp } from "@/types/common";
import { notificationResource, requireFound } from "./_support";
import type {
  ListNotificationsInput,
  MarkNotificationReadInput,
  UpdateNotificationPreferenceInput,
} from "@/schemas/notification";
import type { OrgId, Page, UserId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type {
  Notification,
  NotificationChannel,
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export type NotificationPayload = {
  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const rows = [];

  for (const recipientId of new Set(recipients)) {
    if (recipientId === payload.actorId) continue;

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    const channels = resolveChannels(preference, flags);
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      channels,
    });
  }

  return notificationRepo.insertNotifications(orgId, rows);
}

export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:read",
    notificationResource(input.orgId, input.recipientId),
  );
  return notificationRepo.listNotifications(input);
}

export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, actor.userId),
  );
  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

export async function markAllRead(
  actor: Actor,
  orgId: OrgId,
): Promise<number> {
  assertOrgScope(actor, orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(orgId, actor.userId),
  );
  return notificationRepo.markAllRead(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
}

export async function updatePreference(
  actor: Actor,
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, input.userId),
  );
  return preferenceRepo.upsertPreference(input);
}

/**
 * Turns a stored preference into the channels one notification will use.
 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
 * the email channel additionally requires the org's `digest_email` plan flag.
 */
export function resolveChannels(
  preference: NotificationPreference | null,
  flags: FlagContext,
): readonly NotificationChannel[] {
  if (preference === null) return DEFAULT_CHANNELS;

  const channels: NotificationChannel[] = [];
  if (preference.inApp) channels.push("in_app");

  const emailAllowed =
    preference.email &&
    (!preference.digestOnly || isEnabled("digest_email", flags));

  if (emailAllowed) channels.push("email");
  return channels;
}

/**
 * The bus wiring. Attached at module load rather than from `event-registry`
 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: `/issues/${payload.issueId}`,
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href: `/issues/${payload.issueId}`,
          actorId: payload.actorId,
        },
      );
    }
  });

  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined as ${payload.role}`,
      href: "/settings/members",
      actorId: payload.userId,
    });
  });
}

registerFanOut();
